snippet_css:
:root{
  --bg: #F7F4EE;
  --fg: #2E2D2B;
  --muted: #5A574F;
  --surface: #EDE6DA;
  --border: #D9D1C3;
  --accent: #4A5741;
  --accent-fg: #FFFFFF;
  --accent-grad: linear-gradient(90deg,#C8AD8D,#B49673);
  --radius: 6px;
  --radius-sm: 4px;
  --shadow: 0 10px 30px rgba(46,45,43,.08);
  --btn-shadow: 0 1px 0 rgba(46,45,43,.14);
  --art-bg: linear-gradient(180deg,#EDE6DA,#C8AD8D);
  --media-bg: linear-gradient(180deg,#EDE6DA,#D9D1C3);
  --cta-bg: #EDE6DA;
  --input-bg: #FFFFFF;
  --ok: #3F6B4E;
  --warn: #A6483A;
  --font-display: Jost,'Noto Sans TC',sans-serif;
  --font-body: Jost,'Noto Sans TC',sans-serif;
  --font-mono: ui-monospace,'SF Mono',Menlo,monospace;
  --focus-ring: var(--accent);
}

